local ActionDarkDreamRewardPopup = Class("ActionDarkDreamRewardPopup")
local CellPath = "Game.UI.FightReady.ChaoticRecall.Cell.ActionDarkDreamRewardPopupCell"
local ChaoticRecallUtils = import("Game.UI.FightReady.ChaoticRecall.ChaoticRecallUtils")

function ActionDarkDreamRewardPopup:__init()
    self.curStar = 0
end

function ActionDarkDreamRewardPopup:__delete()
    self.controller = nil
    self.curStar = nil
end

function ActionDarkDreamRewardPopup:Awake()
    SetButtonAction(self.BtnClose1.gameObject,Bind(self,self.OnBtnCloseClick))
    SetButtonAction(self.FontStyleButton.gameObject,Bind(self,self.OnBtnOneKeyGet))
end

function ActionDarkDreamRewardPopup:OnFocus(focus)

end

function ActionDarkDreamRewardPopup:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            self.parameters = self.controller.Argument.parameters
            if not isNull(self.parameters.index) then
                self.curIndex = self.parameters.index
                local dojo = ChaoticRecallUtils.GetChaoticRecallMgr():GetHomeDojo()
                self.groupId = dojo:GetGroupId(self.curIndex)
                self.curStar = dojo:GetAllPassStar(self.curIndex)
                self:RefreshShow()
            end
        end)
    end))
    return coWait
end

function ActionDarkDreamRewardPopup:RefreshShow()
    self.allVos = ChaoticRecallUtils.GetVosByGroupId(self.groupId)
    table.sort(self.allVos,function(a,b)
        local aIsGet = self:JudgeIsGet(a.starLevel) and 1 or 0
        local bIsGet = self:JudgeIsGet(b.starLevel) and 1 or 0
        if aIsGet == bIsGet then
            return a.id < b.id
        else
            return aIsGet < bIsGet
        end
    end)

    if not self.RewardLoopView.IsListViewInit then
        self.RewardLoopView:InitListView(#self.allVos, Bind(self, self.OnGetItemByIndex))
        self.RewardLoopView:UpdateDisplayItemCount("Cell")
    else
        GameUtils.ReloadData(self.RewardLoopView, #self.allVos)
    end
end

function ActionDarkDreamRewardPopup:OnGetItemByIndex(listView,index)
    if index < 0 or index >= #self.allVos then
        return
    end

    local cell = listView:NewListViewItem("Cell")
    if not isNull(cell) then
        local tableCellEnv = CfUtils.GetLuaScr(cell, CellPath)
        if not isNull(tableCellEnv) then
            local data = self.allVos[index + 1]
            local isGet = self:JudgeIsGet(data.starLevel)
            tableCellEnv:SetCallBack(Bind(self,self.OnGetRewardClick))
            tableCellEnv:RefreshShow(data,isGet,self.curStar)
            if listView.DisplayItemNumber < listView.DisplayItemCount then
                tableCellEnv:PlayAnimByEnter(listView.DisplayItemNumber)
                listView.DisplayItemNumber = listView.DisplayItemNumber + 1
            else
                tableCellEnv:PlayAnimByShowed()
            end
        end
    end
    return cell
end

function ActionDarkDreamRewardPopup:OnGetRewardClick(starLevel)
    GameUtils.Request(Interfaces.OverseaNightmareDrawStarReward,{groupId = self.groupId,star = starLevel},function(request,response)
        if checkInt(response.errCode) == 0 then
            local data = response.data

            local dojo = ChaoticRecallUtils.GetChaoticRecallMgr():GetHomeDojo()
            if not isNull(dojo) then
                dojo:UpdateStarReceive(self.curIndex,starLevel)
            end

            GameUtils.ReloadData(self.RewardLoopView, #self.allVos)

            Events.Broadcast("ActionDarkDreamMainDialogRefreshRedPoint")

            if table.count(data.rewards) >  0 then
                GoodsUtils.DrawRewards(data.rewards)
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = data.rewards }})
            end
        end
    end)
end

function ActionDarkDreamRewardPopup:OnBtnOneKeyGet()
    local isHaveReward = self:IsHaveReward()
    if not isHaveReward then
        GameUtils.Toast(localize("暂无可领取的奖励"))
        return
    end


    GameUtils.Request(Interfaces.OverseaNightmareOnKeyDrawStarReward,{groupId = self.groupId},function(request,response)
        if checkInt(response.errCode) == 0 then
            local data = response.data

            local dojo = ChaoticRecallUtils.GetChaoticRecallMgr():GetHomeDojo()
            if not isNull(dojo) then
                dojo:UpdateAllStarReceive(self.curIndex,data.receiveStars)
            end

            GameUtils.ReloadData(self.RewardLoopView, #self.allVos)

            Events.Broadcast("ActionDarkDreamMainDialogRefreshRedPoint")

            if table.count(data.rewards) >  0 then
                GoodsUtils.DrawRewards(data.rewards)
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = data.rewards }})
            end
        end
    end)
end

function ActionDarkDreamRewardPopup:IsHaveReward()
    for i, v in pairs(self.allVos) do
        local isGet = self:JudgeIsGet(v.starLevel)
        if not isGet and self.curStar >= v.starLevel then
            return true
        end
    end
    return false
end

function ActionDarkDreamRewardPopup:JudgeIsGet(level)
    local dojo = ChaoticRecallUtils.GetChaoticRecallMgr():GetHomeDojo()
    local data = dojo:GetStarReceiveData(self.curIndex)
    for i, v in pairs(data) do
        if v == level then
            return true
        end
    end
    return false
end

